// Roll the current brand icon (Logo/final-v2) out to every place the app draws
// its own logo. Run after build-new-icon.mjs, from the Logo folder:
//
//   node apply-icon-to-app.mjs
//
// The Tauri app/installer/store/mobile icons under src-tauri/icons are NOT
// handled here -- those are generated by the Tauri CLI:
//
//   bun run tauri icon Logo/final-v2/png/icon-1024.png
//
// Deliberately left alone: src-tauri/resources/tray_recording*.png,
// tray_transcribing*.png, recording.png and transcribing.png. Those are
// recording/transcribing STATE glyphs (flat monochrome shapes), not the brand
// mark, and replacing them with the tile would erase the tray's state feedback.

import fs from "node:fs";
import path from "node:path";
import sharp from "sharp";

const MASTER = path.join("final-v2", "icon-master-2048.png");
const REPO = "..";

// Same small-size sharpening policy as build-new-icon.mjs: below ~96px a plain
// lanczos downsample greys the waveform bars into the tile.
const SHARPEN_BELOW = 96;
function render(size) {
  let pipe = sharp(MASTER).resize(size, size, { kernel: "lanczos3" });
  if (size < SHARPEN_BELOW) {
    pipe = pipe.sharpen({
      sigma: 0.6 + 0.6 * (1 - size / SHARPEN_BELOW),
      m1: 0,
      m2: 2.2,
    });
  }
  return pipe.png({ compressionLevel: 9 });
}

// [destination, size, why]
const TARGETS = [
  // System tray. All three are the same colour tile today: Windows and macOS
  // read tray_idle*, Linux reads speakoflow.png via AppTheme::Colored.
  ["src-tauri/resources/tray_idle.png", 64, "tray idle (dark themes)"],
  ["src-tauri/resources/tray_idle_dark.png", 64, "tray idle (light themes)"],
  ["src-tauri/resources/speakoflow.png", 64, "tray idle (Linux)"],
  // Taskbar / alt-tab / dock. tray.rs picks light vs dark by theme, but both
  // slots hold the same full-colour tile, which reads on either background.
  ["src-tauri/resources/window_icon_light.png", 256, "taskbar + alt-tab"],
  ["src-tauri/resources/window_icon_dark.png", 256, "taskbar + alt-tab"],
  // SpeakoFlow Mini's badge in the model catalogue (largest tile drawn is 40px;
  // 128 keeps 3x headroom).
  ["src/assets/speakoflow-mini.png", 128, "SpeakoFlow Mini model badge"],
];

for (const [rel, size, why] of TARGETS) {
  const dest = path.join(REPO, rel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  await render(size).toFile(dest);
  console.log(
    `${rel.padEnd(46)} ${String(size).padStart(4)}px  ${fs.statSync(dest).size}b  (${why})`,
  );
}

// public/favicon.svg is referenced by all three window entry points
// (index.html, src/assistant, src/overlay). The new artwork is raster, so the
// SVG is a container around it; 192px is ample for a favicon and keeps the file
// small enough to ship in the bundle.
const FAVICON_PX = 192;
const b64 = (await render(FAVICON_PX).toBuffer()).toString("base64");
const favicon = path.join(REPO, "public/favicon.svg");
fs.writeFileSync(
  favicon,
  `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${FAVICON_PX}" height="${FAVICON_PX}" viewBox="0 0 ${FAVICON_PX} ${FAVICON_PX}">
  <title>SpeakoFlow</title>
  <image width="${FAVICON_PX}" height="${FAVICON_PX}" xlink:href="data:image/png;base64,${b64}"/>
</svg>
`,
);
console.log(
  `${"public/favicon.svg".padEnd(46)} ${String(FAVICON_PX).padStart(4)}px  ${fs.statSync(favicon).size}b  (window favicons)`,
);

// docs-site favicon (the docs site's own logo lockups are written by
// build-new-lockup.mjs).
const docsFavicon = path.join(REPO, "docs-site/favicon.png");
if (fs.existsSync(docsFavicon)) {
  await render(256).toFile(docsFavicon);
  console.log(
    `${"docs-site/favicon.png".padEnd(46)}  256px  ${fs.statSync(docsFavicon).size}b  (docs site)`,
  );
}

console.log("\nDONE.");
